#include <math.h>
#include <stdlib.h>
#include <string.h>

// Power iteration to find dominant eigenvalue and eigenvector
// Returns 0 on success, -1 on failure
int power_iteration(const double *A, int n, double *eigenvalue, double *eigenvector) {
    // Initialize with a random-ish vector
    double *v = (double *)malloc(n * sizeof(double));
    double *v_new = (double *)malloc(n * sizeof(double));
    double *w = (double *)malloc(n * sizeof(double));

    // Use a deterministic starting vector
    for (int i = 0; i < n; i++) {
        v[i] = 1.0 / sqrt((double)n);
    }

    double max_iter = 1000;
    double tol = 1e-14;

    for (int iter = 0; iter < max_iter; iter++) {
        // w = A * v
        for (int i = 0; i < n; i++) {
            w[i] = 0.0;
            for (int j = 0; j < n; j++) {
                w[i] += A[i * n + j] * v[j];
            }
        }

        // Compute norm of w
        double norm = 0.0;
        for (int i = 0; i < n; i++) {
            norm += w[i] * w[i];
        }
        norm = sqrt(norm);

        if (norm < 1e-30) {
            // Zero vector - try different starting vector
            for (int i = 0; i < n; i++) {
                v[i] = (double)(i + 1);
            }
            continue;
        }

        // v_new = w / ||w||
        for (int i = 0; i < n; i++) {
            v_new[i] = w[i] / norm;
        }

        // Check convergence
        double diff = 0.0;
        for (int i = 0; i < n; i++) {
            double d = v_new[i] - v[i];
            diff += d * d;
        }
        diff = sqrt(diff);

        // Copy v_new to v
        memcpy(v, v_new, n * sizeof(double));

        if (diff < tol) break;
    }

    // Compute eigenvalue via Rayleigh quotient: lambda = v^T A v
    // First compute Av
    for (int i = 0; i < n; i++) {
        w[i] = 0.0;
        for (int j = 0; j < n; j++) {
            w[i] += A[i * n + j] * v[j];
        }
    }

    double lambda = 0.0;
    for (int i = 0; i < n; i++) {
        lambda += v[i] * w[i];
    }

    *eigenvalue = lambda;
    for (int i = 0; i < n; i++) {
        eigenvector[i] = v[i];
    }

    free(v);
    free(v_new);
    free(w);

    return 0;
}

// For 2x2 matrices, use analytical solution
int eigen_2x2(const double *A, double *eigenvalue, double *eigenvector) {
    double a = A[0], b = A[1], c = A[2], d = A[3];
    double trace = a + d;
    double det = a * d - b * c;
    double disc = trace * trace - 4.0 * det;

    if (disc >= 0) {
        // Real eigenvalues
        double sqrt_disc = sqrt(disc);
        double e1 = (trace + sqrt_disc) / 2.0;
        double e2 = (trace - sqrt_disc) / 2.0;

        if (fabs(e1) >= fabs(e2)) {
            *eigenvalue = e1;
            // eigenvector for e1: (b, e1-a) or (e1-d, c)
            if (fabs(b) > 1e-15) {
                double norm = sqrt(b * b + (e1 - a) * (e1 - a));
                eigenvector[0] = b / norm;
                eigenvector[1] = (e1 - a) / norm;
            } else {
                eigenvector[0] = (e1 - d) / sqrt((e1-d)*(e1-d) + c*c);
                eigenvector[1] = c / sqrt((e1-d)*(e1-d) + c*c);
            }
        } else {
            *eigenvalue = e2;
            if (fabs(b) > 1e-15) {
                double norm = sqrt(b * b + (e2 - a) * (e2 - a));
                eigenvector[0] = b / norm;
                eigenvector[1] = (e2 - a) / norm;
            } else {
                eigenvector[0] = (e2 - d) / sqrt((e2-d)*(e2-d) + c*c);
                eigenvector[1] = c / sqrt((e2-d)*(e2-d) + c*c);
            }
        }
    } else {
        // Complex eigenvalues - use power iteration
        return power_iteration(A, 2, eigenvalue, eigenvector);
    }
    return 0;
}
