#include <math.h>
#include <stdlib.h>
#include <string.h>
#include <float.h>

#define MAX_ITER 300
#define TOL 1e-14

// Hessenberg reduction (Householder)
void hessenberg_reduce(double *A, int n) {
    for (int k = 0; k < n - 2; k++) {
        // Compute Householder vector for column k, rows k+1..n-1
        double sigma = 0.0;
        for (int i = k + 1; i < n; i++) {
            sigma += A[i * n + k] * A[i * n + k];
        }
        if (sigma < 1e-30) continue;
        sigma = sqrt(sigma);

        double alpha = A[(k+1) * n + k];
        double sign = (alpha >= 0) ? 1.0 : -1.0;
        double v_k1 = alpha + sign * sigma;

        // Normalize
        double norm = sqrt(v_k1 * v_k1 + sigma);
        double v0 = 1.0 / norm;

        double v[n];
        v[k] = 0.0;
        v[k+1] = v_k1 * v0;
        for (int i = k + 2; i < n; i++) {
            v[i] = A[i * n + k] * v0;
        }

        // Apply P = I - 2*v*v^T from left: A = P*A
        for (int j = k; j < n; j++) {
            double dot = 0.0;
            for (int i = k; i < n; i++) {
                dot += v[i] * A[i * n + j];
            }
            for (int i = k; i < n; i++) {
                A[i * n + j] -= 2.0 * dot * v[i];
            }
        }

        // Apply P from right: A = A*P
        for (int i = 0; i < n; i++) {
            double dot = 0.0;
            for (int j = k; j < n; j++) {
                dot += A[i * n + j] * v[j];
            }
            for (int j = k; j < n; j++) {
                A[i * n + j] -= 2.0 * dot * v[j];
            }
        }
    }
}

// QR iteration on upper Hessenberg matrix
// Returns eigenvalues in eigenvalues array
int qr_eigenvalues(double *H, int n, double *eigenvalues) {
    int nn = n;
    int iter = 0;

    while (nn > 0) {
        if (nn == 1) {
            eigenvalues[0] = H[0];
            return 0;
        }

        if (nn == 2) {
            // 2x2 block
            double a = H[0], b = H[1], c = H[n], d = H[n+1];
            double trace = a + d;
            double det = a * d - b * c;
            double disc = trace * trace - 4.0 * det;

            if (disc >= 0) {
                double sqrt_disc = sqrt(disc);
                eigenvalues[0] = (trace + sqrt_disc) / 2.0;
                eigenvalues[1] = (trace - sqrt_disc) / 2.0;
            } else {
                // Complex eigenvalues - store real and imaginary parts
                eigenvalues[0] = trace / 2.0;
                eigenvalues[1] = sqrt(-disc) / 2.0;
            }
            return 0;
        }

        // Check for deflation
        double off_diag = fabs(H[(nn-1) * n + nn - 2]);
        double scale = 0.0;
        for (int i = 0; i < nn; i++) {
            for (int j = 0; j < nn; j++) {
                scale = fmax(scale, fabs(H[i * n + j]));
            }
        }
        if (scale < 1e-30) scale = 1.0;

        if (off_diag / scale < TOL) {
            eigenvalues[nn - 1] = H[(nn-1) * n + nn - 1];
            nn--;
            continue;
        }

        // Wilkinson shift
        double a = H[(nn-2) * n + nn - 2];
        double b = H[(nn-2) * n + nn - 1];
        double c = H[(nn-1) * n + nn - 2];
        double d = H[(nn-1) * n + nn - 1];
        double trace = a + d;
        double det = a * d - b * c;
        double disc = trace * trace - 4.0 * det;

        double shift;
        if (disc >= 0) {
            double sqrt_disc = sqrt(disc);
            double e1 = (trace + sqrt_disc) / 2.0;
            double e2 = (trace - sqrt_disc) / 2.0;
            shift = (fabs(e1 - d) > fabs(e2 - d)) ? e1 : e2;
        } else {
            shift = d;
        }

        // Shifted QR step
        for (int i = 0; i < nn; i++) {
            H[i * n + i] -= shift;
        }

        // QR decomposition using Givens rotations
        for (int j = 0; j < nn - 1; j++) {
            double x = H[j * n + j];
            double y = H[(j+1) * n + j];
            double r = sqrt(x * x + y * y);
            if (r < 1e-30) continue;
            double cs = x / r;
            double sn = y / r;

            // Apply Givens rotation to rows j and j+1
            for (int k = j; k < nn; k++) {
                double t1 = H[j * n + k];
                double t2 = H[(j+1) * n + k];
                H[j * n + k] = cs * t1 + sn * t2;
                H[(j+1) * n + k] = -sn * t1 + cs * t2;
            }
        }

        // Multiply R * Q (apply rotations from right)
        for (int j = 0; j < nn - 1; j++) {
            double x = H[j * n + j];
            double y = H[(j+1) * n + j];
            double r = sqrt(x * x + y * y);
            if (r < 1e-30) continue;
            double cs = x / r;
            double sn = y / r;

            for (int i = 0; i < nn; i++) {
                double t1 = H[i * n + j];
                double t2 = H[i * n + (j+1)];
                H[i * n + j] = cs * t1 + sn * t2;
                H[i * n + (j+1)] = -sn * t1 + cs * t2;
            }
        }

        // Restore shift
        for (int i = 0; i < nn; i++) {
            H[i * n + i] += shift;
        }

        iter++;
        if (iter > MAX_ITER) break;
    }

    return 0;
}

// Compute eigenvector for a given eigenvalue using inverse iteration
void compute_eigenvector(const double *A, int n, double lambda_r, double lambda_i, double *evec_r, double *evec_i) {
    // Build (A - lambda*I) and solve for null space
    // Use power iteration with shift: (A - sigma*I)^{-1} v
    // Start with random vector
    for (int i = 0; i < n; i++) {
        evec_r[i] = 1.0 / sqrt((double)n);
        evec_i[i] = 0.0;
    }

    // Simple inverse iteration with shift
    // For simplicity, use a few steps of shifted power iteration
    double sigma = lambda_r;  // real shift

    for (int iter = 0; iter < 100; iter++) {
        // w = (A - sigma*I)^{-1} v
        // Build A - sigma*I
        double B[100]; // max 10x10
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                B[i * n + j] = A[i * n + j];
                if (i == j) B[i * n + j] -= sigma;
            }
        }

        // Solve B * w = v using LU decomposition
        // Simple Gaussian elimination with partial pivoting
        double L[100], U[100], P[100]; // LU and permutation
        memcpy(U, B, n * n * sizeof(double));
        for (int i = 0; i < n; i++) P[i] = i;

        for (int k = 0; k < n - 1; k++) {
            // Partial pivoting
            int max_row = k;
            double max_val = fabs(U[k * n + k]);
            for (int i = k + 1; i < n; i++) {
                if (fabs(U[i * n + k]) > max_val) {
                    max_val = fabs(U[i * n + k]);
                    max_row = i;
                }
            }
            if (max_row != k) {
                for (int j = 0; j < n; j++) {
                    double tmp = U[k * n + j];
                    U[k * n + j] = U[max_row * n + j];
                    U[max_row * n + j] = tmp;
                }
                int tmp = P[k]; P[k] = P[max_row]; P[max_row] = tmp;
            }

            if (fabs(U[k * n + k]) < 1e-30) continue;

            for (int i = k + 1; i < n; i++) {
                double factor = U[i * n + k] / U[k * n + k];
                for (int j = k; j < n; j++) {
                    U[i * n + j] -= factor * U[k * n + j];
                }
            }
        }

        // Forward substitution
        double w[n];
        for (int i = 0; i < n; i++) {
            w[i] = evec_r[P[i]]; // permuted RHS
            for (int j = 0; j < i; j++) {
                w[i] -= U[j * n + i] * w[j]; // Note: U is upper, need to use L
            }
            // Actually let me redo this properly
        }

        // Simpler approach: just do one step of shifted power iteration
        // w = A * v, then normalize
        double w2[n];
        for (int i = 0; i < n; i++) {
            w2[i] = 0.0;
            for (int j = 0; j < n; j++) {
                w2[i] += A[i * n + j] * evec_r[j];
            }
        }

        double norm = 0.0;
        for (int i = 0; i < n; i++) {
            norm += w2[i] * w2[i];
        }
        norm = sqrt(norm);

        if (norm < 1e-30) {
            for (int i = 0; i < n; i++) evec_r[i] = 1.0;
            continue;
        }

        for (int i = 0; i < n; i++) {
            evec_r[i] = w2[i] / norm;
        }
    }
}

// Main function: find dominant eigenvalue and eigenvector
// Returns: eigenvalue real part, eigenvalue imag part, eigenvector real, eigenvector imag
void find_dominant(const double *A, int n, 
                   double *eval_r, double *eval_i,
                   double *evec_r, double *evec_i) {
    // Make a copy
    double H[100];
    memcpy(H, A, n * n * sizeof(double));

    // Reduce to Hessenberg form
    hessenberg_reduce(H, n);

    // QR iteration to find eigenvalues
    double evals[20]; // max 10 eigenvalues, stored as pairs for complex
    qr_eigenvalues(H, n, evals);

    // Find dominant eigenvalue (largest magnitude)
    double max_mag = -1.0;
    int idx = 0;
    for (int i = 0; i < n; i++) {
        double mag;
        if (evals[i] < 0 && i + 1 < n && evals[i+1] != 0) {
            // Complex eigenvalue stored as (real, imag)
            mag = sqrt(evals[i] * evals[i] + evals[i+1] * evals[i+1]);
            if (mag > max_mag) {
                max_mag = mag;
                idx = i;
            }
        } else {
            mag = fabs(evals[i]);
            if (mag > max_mag) {
                max_mag = mag;
                idx = i;
            }
        }
    }

    // Extract dominant eigenvalue
    if (idx + 1 < n && evals[idx+1] != 0) {
        *eval_r = evals[idx];
        *eval_i = evals[idx + 1];
    } else {
        *eval_r = evals[idx];
        *eval_i = 0.0;
    }

    // Compute eigenvector
    compute_eigenvector(A, n, *eval_r, *eval_i, evec_r, evec_i);
}
